window.REPORT_PRELOAD_CACHE["PAYX.html"] = {"version":"cbafd5576257fcd97c03dbf205b3963ef7eba22a1be8b1c55dd442359c4e987e","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>派克西 Paychex Inc. (NASDAQ: PAYX) 深度研究报告：美国中小企业 HCM 巨头、Paycor 战略整合与高现金流红利印钞机</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n payxred: {\n 300: '#FCA5A5',\n 400: '#F87171',\n 500: '#EF4444',\n 600: '#DC2626',\n 700: '#B91C1C',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n teal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n /* 自定义滚动条与机构研报细节排版 */\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n /* 打印友好优化 */\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n /* 卡片悬浮微光与上移过渡 */\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n /* 侧边导航激活态：Paychex 红渐变底色 */\n .nav-link.active {\n background: linear-gradient(90deg, rgba(239, 68, 68, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #EF4444;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-payxred-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-payxred-600 via-payxred-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-payxred-500 to-payxred-700 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n PAYX\n </div>\n <div>\n <div class=\"text-[11px] text-payxred-400 font-semibold tracking-wider uppercase\">NASDAQ: PAYX · HCM Leader</div>\n <div class=\"text-sm font-bold leading-tight\">派克西 Paychex 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">PAYX 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与 Paycor 整合红利</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重核心护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球人力资本巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与股息复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与三情景估值</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球人力资源与企业SaaS研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (FY26 / Q3)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-payxred-400 via-payxred-500 to-payxred-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-payxred-500/25\">\n PAY\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-payxred-400 bg-payxred-500/15 px-2 py-0.5 rounded\">NASDAQ: PAYX</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">派克西深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 美国中小企业 HCM 霸主 · 约 84 万家企业客户与高复利现金机器\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$115.68 <span class=\"text-slate-400 text-[10px]\">($85.4-$128)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY26 调整后 EPS</span>\n <span class=\"font-mono font-bold text-emerald-400\">~$4.80–$5.00 <span class=\"text-slate-400\">(+11%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值与股息率</span>\n <span class=\"font-mono font-bold text-payxred-400\">~20.5x P/E · 股息率 4.1%</span>\n </div>\n </div>\n\n <!-- 七大核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-payxred-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与 Paycor 整合红利</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球人力资本巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与股息复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与三情景估值</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-payxred-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-payxred-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-payxred-500 to-payxred-600 hover:from-payxred-600 hover:to-payxred-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-payxred-500/15 text-payxred-700 dark:text-payxred-400 font-bold border border-payxred-500/30\">评级：买入 / 高分红与企业 SaaS 核心防御底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 财年 Paycor 深度协同与业绩超预期兑现期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: PAYX</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#EF4444 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-payxred-500/20 border border-payxred-400/40 text-payxred-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-payxred-400 animate-pulse\"></span>\n <span>CORE THESIS · 美国 1/11 名劳动者薪酬管理霸主 × Paycor 并购协同大放异彩 × ~4.1% 稳健股息率与高现金流</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 派克西 Paychex, Inc. (NASDAQ: PAYX) 深度研究报告：美国中小企业 HCM 霸主、Paycor 战略整合与高现金流红利印钞机\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 派克西（Paychex）作为全美中小企业人力资本管理（HCM）与薪酬外包领域的双子星，在最新发布的财报中交出亮眼答卷：总营收同比大增 <strong class=\"text-payxred-300\">20% 达 $18 亿</strong>，调整后 EPS 达 <strong class=\"text-white\">$1.71（超越市场预期）</strong>。\n 得益于战略收购 <strong class=\"text-white\">Paycor HCM（2025年4月交割）</strong>带来的深度协同，管理解决方案业务飙升 23%，叠加客户资金托管利息（Client Fund Interest）的稳定加持，公司营业利润率稳居 <strong class=\"text-emerald-400\">43%+</strong> 行业高位。凭借服务全美约 84 万家客户、管理全美约 1/11 名劳动者薪酬的庞大基本盘，Paychex 持续为长线投资者提供兼具成长性与高股息率（~4.1%）的优质避风港。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">庞大客户与市占率</div>\n <div class=\"text-white font-semibold\">服务全美约 84 万家企业客户，管理全美约 11% 劳动者薪酬，粘性极高且几乎无惧宏观微小波动</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Paycor 协同效应加速释放</div>\n <div class=\"text-payxred-400 font-semibold\">收购 Paycor 显著拓展中端市场（Upmarket）客群，管理解决方案收入连续大增 20%+</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">丰厚股东现金回报</div>\n <div class=\"text-emerald-400 font-semibold\">股息率达 ~4.1%，多年连续派息与回购，自由现金流转换率接近 100%，堪称全美 SaaS 现金牛</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-payxred-500/15 text-payxred-600 dark:text-payxred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$41.4B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$115.68</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 全美领先的科技驱动人力资源与薪酬管理巨头，52 周交易区间在 $85.4 至 $128.0 之间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY26 调整后 EPS 指引</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$4.80–$5.00</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+11% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季调整后 EPS 达 $1.71 超越预期，全年营收增长指引稳步锁定在 16.5%–18.5%。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>营业利润率 & 运营现金流</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">43.8%</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">CFO $2.0B+</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 凭借出色的定价权与费用控制，每 1 美元营收中超过 40 美分转化为营业利润，现金流极为充沛。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>股息率与股东总回报</span>\n <span class=\"p-1.5 rounded-lg bg-payxred-500/15 text-payxred-600 dark:text-payxred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~4.1%</span>\n <span class=\"text-xs font-bold text-payxred-700 dark:text-payxred-400 bg-payxred-500/15 px-2 py-0.5 rounded\">Total Yield ~5.1%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 连续 39 年派发股息、连续 12 年稳步上调，搭配股份回购，为股东构筑双重现金回报防御垫。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务架构与 Paycor 整合红利 (Business & Paycor Integration)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-payxred-600 dark:text-payxred-400\">Section 01 · Business Architecture & Paycor Synergies</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与 Paycor 整合红利：管理解决方案、PEO 服务的双轮驱动</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26 总营收预计增长 16.5%–18.5% · 客户数突破 84 万</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 净营收与管理解决方案分部演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">得益于有机增长与 Paycor 并购赋能，管理解决方案营收实现跨越式增长</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-payxred-600 dark:text-payxred-400 shadow-sm transition cursor-pointer\">视图A：营收分部与增长结构</button>\n <button onclick=\"switchBizChart('metrics_split')\" id=\"btn-chart-met\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：关键经营指标拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">三大核心业务支柱与协同突破</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-payxred-500/15 text-payxred-600 dark:text-payxred-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">管理解决方案 (Management Solutions)：大增 23% 至 $13.5亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核心薪酬、HR 软件及考勤服务。4 月并表的 Paycor 贡献了约 19% 的板块营收增速，同时 Paycor 的中端市场（Upmarket）销售团队成功与经纪人渠道深度打通。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-orange-500/15 text-orange-600 dark:text-orange-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">专业雇主组织与保险 (PEO & Insurance Solutions)：稳健增长 9%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n PEO 业务实现双位数强劲预定增长，客户留存率（WSE Retention）创下历史新高，为中小企业提供合规、员工福利与工伤保险全包方案。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">客户资金托管利息 (Interest on Client Funds)：大增 33%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 伴随 Paycor 加入带来的庞大日均客户资金沉淀，全年客户端利息收入预计维持在 $2.0亿–$2.1 亿美元的高回报区间。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">长期战略锚点</span>\n <span class=\"font-bold text-payxred-600 dark:text-payxred-400\">AI 赋能 HCM 矩阵与高端客户穿透</span>\n </div>\n </div>\n </div>\n\n <!-- 四大业务矩阵 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-payxred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-payxred-500/15 text-payxred-700 dark:text-payxred-400 text-xs font-bold\">核心基石 · 薪酬与人力资源管理软件</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">板块收入大增 +23%</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 管理解决方案 (Management Solutions)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 为全美 84 万家中小企业提供自动化薪资发放、税务申报、HR 档案管理、员工自助端（Self-service）及时间考勤。收购 Paycor 后，产品矩阵成功由传统小微企业向上延伸至中端规模客户（Upmarket）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>Q3 收入达 $13.5 亿</span>\n <span class=\"text-payxred-600 dark:text-payxred-400 font-semibold\">Paycor 协同效益全线落地</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-orange-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-orange-500/15 text-orange-700 dark:text-orange-400 text-xs font-bold\">高客单价全包服务 · 稳健增长 9%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">WSE 留存创历史新高</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 专业雇主组织与保险 (PEO & Insurance Solutions)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 采用共同雇主模式（Co-employment），为中小企业打包提供人事管理、福利计划、风险合规与工伤保险。PEO 业务展现出极强的市场抗跌性，工作现场雇员（WSE）数量维持高单数字增长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>Q3 收入 $3.975 亿 (+9%)</span>\n <span class=\"text-orange-600 dark:text-orange-400 font-semibold\">超越行业的客户留存率</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/15 text-teal-700 dark:text-teal-400 text-xs font-bold\">高收益资金托管 · 纯利增厚</span>\n <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">利息收入大增 +33%</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">3. 客户资金托管利息 (Interest on Client Funds)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 在为企业代发薪酬前，Payx 需提前归集并暂存客户的薪资与税款资金池。伴随高利率周期及 Paycor 收购带来的庞大投资组合余额，Q3 客户端利息收入达 $5,680 万美元（同比 +33%）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>全年指引 $2.0亿–$2.1亿美元</span>\n <span class=\"text-teal-600 dark:text-teal-400 font-semibold\">无风险资金运作利息收益</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/15 text-indigo-700 dark:text-indigo-400 text-xs font-bold\">AI 赋能与数字化产品矩阵</span>\n <span class=\"font-mono text-xs font-bold text-indigo-600 dark:text-indigo-400\">自动化智能助手</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">4. 人工智能与数字化增值服务 (AI-Powered HCM)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 全面将 AI 嵌入 HCM 平台，提供智能招聘筛选、合规自动提醒、HR 智能问答机器人与员工流失预测分析，大幅降低中小企业 HR 管理门槛并提升每用户平均收入（ARPU）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>全面驱动服务效率与粘性</span>\n <span class=\"text-indigo-600 dark:text-indigo-400 font-semibold\">AI 时代的 HCM 基础设施</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Economic Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：高转换成本、合规壁垒与 43%+ 营业利润率</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Economic Moat)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-payxred-500/15 text-payxred-600 dark:text-payxred-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极高的客户转换成本 (High Switching Costs)</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 薪酬与税务合规是企业运营的生命线。一旦中小企业将员工档案、薪资结构及税表接入 Paychex 系统，因害怕出现合规漏报或薪发放事故，几乎极少主动更换供应商，客户留存率常年保持在极高水平。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">错综复杂的美国联邦与州级税务合规高墙</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 美国各州及地方税务法律繁杂且频繁变动。Paychex 拥有数十年积累的专业税务合规数据库与专家团队，确保中小企业免受天价罚单困扰，这是中小型竞争对手难以在短期内超越的软实力。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">广泛的 CPA 经纪人与分销渠道网络</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n Paychex 与全美数十万名注册会计师（CPA）和财务顾问建立了长达数十年的深度转介合作关系，构建了极为坚固且低获客成本的独特分销网络。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">43%+ 卓越的营业利润率与现金生成质地</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 依托成熟的软件 SaaS 架构与规模化运营，每 1 美元营收可创造约 40 美分以上的营业利润。高质量的现金流保证了公司连续 39 年不间断分红及持续回购的能力。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">人力资本管理（HCM）巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">派克西 (PAYX) vs ADP vs Paycom (PAYC)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球人力资本巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-payxred-600 dark:text-payxred-400\">Section 03 · HCM Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球人力资本管理巨头横向对比：ADP、Paychex 与纯SaaS同行估值剖析</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-payxred-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('hcm')\" data-filter=\"hcm\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">传统HCM与薪酬双雄</button>\n <button onclick=\"filterCompetitors('saas')\" data-filter=\"saas\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">纯云端SaaS同行</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心目标客群</th>\n <th class=\"py-4 px-4 min-w-[140px]\">竞争优势与特点</th>\n <th class=\"py-4 px-4 min-w-[100px]\">远期 P/E</th>\n <th class=\"py-4 px-4 min-w-[115px]\">股息率 (Yield)</th>\n <th class=\"py-4 px-4 min-w-[115px]\">营业利润率</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与估值定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"hcm\" class=\"bg-payxred-500/5 dark:bg-payxred-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-payxred-500 text-white text-[10px] font-extrabold\">核心研究标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">派克西 (PAYX)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Paychex, Inc.</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">美国中小企业 (SME)</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-payxred-500/15 text-payxred-700 dark:text-payxred-400\">84万客户 + Paycor整合</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~20.5x</td>\n <td class=\"py-4 px-4 font-mono font-bold text-payxred-600 dark:text-payxred-400\">~4.1%</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~43.8%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>中小企业薪酬外包霸主：</strong>估值性价比高，股息率高达 4.1%，现金流稳健，Paycor 协同效应持续兑现。\n </td>\n </tr>\n\n <tr data-category=\"hcm\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">ADP 自动数据处理 (ADP)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Automatic Data Processing</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球中小型至超大型企业</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">全球 HCM 绝对行业龙头</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~26.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~2.2%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~25.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球 HCM 巨无霸：</strong>规模远超 Paychex，跨国企业服务能力顶尖，但估值倍数相对较高。\n </td>\n </tr>\n\n <tr data-category=\"saas\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Paycom Software (PAYC)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Paycom Software, Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">美国中端企业 (Deduct Employee)</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">Beti 自助薪酬自动化</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~24.1x</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">1.5%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~20.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯云端创新 SaaS：</strong>主打员工自主自助薪酬计算（Beti），成长弹性大但受宏观就业率波动较大。\n </td>\n </tr>\n\n <tr data-category=\"saas\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Paylocity Holding (PCTY)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Paylocity Holding Corp.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">中小型现代科技企业</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-teal-500/15 text-teal-700 dark:text-teal-400\">现代化 UI 与出色员工体验</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~21.4x</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">0.0%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~18.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>现代 SaaS 挑战者：</strong>专注于高科技和现代服务业中小企业，产品体验佳，但缺乏 Paychex 庞大的 CPA 渠道护城河。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球 HCM 巨头营业利润率（Operating Margin）与远期 P/E 估值对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Paychex 凭借高效的传统与云端双核运营，以 43.8% 的营业利润率领跑同业</p>\n </div>\n <span class=\"text-xs font-semibold text-payxred-700 dark:text-payxred-400 bg-payxred-500/15 px-2.5 py-1 rounded\">43.8% 营业利润率断层领先</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与股息复利推演 (Financial Health & Dividend Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Dividend Compounding Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与股息复利推演：$19亿经营现金流与“股息+回购”复利引擎</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">连续 39 年派息 · 现金流覆盖率极高</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-payxred-600 dark:text-payxred-400 uppercase\">Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">43.8%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 营业利润率达 43.8%，展现出极佳的规模化 SaaS 运营效率和严格的成本控制纪律。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$1.9B–$2.0B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 经营现金流强劲且高质，常年显著超出净利润水平，自由现金流（FCF）转化率极高。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Corporate Investments</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$1.8B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 截至财报期末持有现金及公司投资总额约 $18 亿美元，资产负债表健康稳定。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Shareholder Return YTD</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$1.5B+</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 财年前三季度已向股东累计派发超过 $12 亿现金股息并执行数亿美元股份回购。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 调整后 EPS 稳步攀升 vs 营业总收入双轨演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Paycor 并购协同与有机增长双管齐下，推动总营收与每股收益稳步跨越新台阶</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-payxred-700 dark:text-payxred-400 bg-payxred-500/15 px-2.5 py-1 rounded\">稳健双位数盈利复利</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 模拟计算器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-payxred-400 font-bold\">\n <span>DIVIDEND & GROWTH COMPOUNDING ENGINE · 高息成长复利模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">派克西 (PAYX) DRIP 复利与成本股息率（Yield on Cost）动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $115.68 | 年化股息 $4.76/股（起始毛股息率 4.11%）| 支持不同税务管辖区预扣税设定</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-payxred-500/15 border border-payxred-400/30 text-xs font-semibold text-payxred-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#EF4444] cursor-pointer\">\n <span>开启股息自动再投资 (DRIP)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投入本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#EF4444] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">10 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#EF4444] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均股息与 EPS 增长率 (预期: 8%–10%)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">8.5%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"3\" max=\"14\" step=\"0.5\" value=\"8.5\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">美股股息预扣税率（Withholding Tax）情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(0)\" data-tax=\"0\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-payxred-400 transition cursor-pointer\">\n 0% 免税账户<br><span class=\"text-[10px] text-slate-400\">IRA/RRSP等</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.10)\" data-tax=\"0.1\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-payxred-500 text-white border border-payxred-400 shadow transition cursor-pointer\">\n 10% 协定税率<br><span class=\"text-[10px] text-slate-200\">中美税收协定</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.30)\" data-tax=\"0.3\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-payxred-400 transition cursor-pointer\">\n 30% 标准预扣<br><span class=\"text-[10px] text-slate-400\">新加坡/香港等</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产 (含税后分红)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$88,450</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +194.8%</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末年度税后股息现金流</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-payxred-400 mt-1.5\">$3,120</div>\n <div id=\"sim-monthly-div\" class=\"text-xs text-slate-400 mt-1.5\">折合每月被动现金流 ~$260</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末税后成本股息率 (Yield on Cost)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">10.40%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">相对于初始投入本金的每年分红回报</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">持有期累计获配税后股息总额</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$18,920</div>\n <div id=\"sim-shares-end\" class=\"text-xs text-slate-400 mt-1.5\">期末持仓股数：331.2 股 (起始 259.4 股)</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">高分红防守 + Paycor协同</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>4.1% 稳定高股息与极强现金流：</strong>在宏观不确定性增加时，Paychex 接近 100% 的现金转化率与连续 39 年派息记录提供极佳防御。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Paycor 并购协同顺利兑现：</strong>成功拓展至高毛利的中端企业市场，经纪人与 CPA 转介渠道产生强大飞轮效应。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>中小企业劳动力市场的刚需：</strong>无论经济如何波动，中小企业发放薪资与税务合规均属于不可停摆的刚性需求。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">宏观就业放缓 + 利率下行风险</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>宏观就业与总工时波动：</strong>若美国中小企业招聘速度放缓或总体就业人数下降，将直接影响 Paychex 按每位员工计费的增量收入。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>客户端利息收入敏感性：</strong>随着美联储货币政策进一步宽松，客户资金托管池产生的利息收入面临边际回落压力。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>Paycor 并购债务与整合摩擦：</strong>收购带来的 $50 亿债务虽在可控范围内，但利息支出及整合过程中的磨合仍需持续跟踪。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与三情景估值框架 (Investment Decision & Valuation)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-payxred-600 dark:text-payxred-400\">Section 05 · Investment Decision & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置：三情景目标价与高息防御底仓策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：逢回调长线吸纳 · 优质红利核心底仓</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">23.0x–25.0x P/E ($130–$145)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>Paycor 协同效益超越预期，中小企业招聘需求强劲复苏，AI 功能大范围落地推升 ARPU，估值中枢随成长溢价上移。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 含息潜在年化总回报：+15% 至 +20%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-payxred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-payxred-500/15 text-payxred-700 dark:text-payxred-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-payxred-600 dark:text-payxred-400\">概率：60%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">19.5x–21.5x P/E ($110–$125)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观经济保持软着陆，营收稳步增长 10%–12%，EPS 维持双位数稳健复利，4.1% 股息率提供坚实底部支撑。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-payxred-600 dark:text-payxred-400\">\n 含息稳健年化总回报：+10% 至 +12%（高确定性收息）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：15%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">16.0x–17.5x P/E ($85–$95)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>美国就业市场显著降温导致中小企业客户流失，或客户端利息收益大幅缩减，压制短期估值倍数。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 含息潜在回撤：-10% 至 -18%（高股息与现金流构筑强力安全垫）\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-payxred-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与高息成长策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 高息成长与防守底仓</div>\n <p class=\"text-slate-300 leading-relaxed\">\n <strong>派克西 (PAYX)</strong> 兼具 SaaS 软件的高毛利属性与传统公用事业类公司的稳定分红特征（~4.1% 股息率），适合作为资产配置中的优质防御底仓。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-payxred-400 mb-1\">2. 价格触发与逢低加仓</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 股价近期平稳运行于 ~$115.68 附近；建议底仓长期持有收息，若遇宏观调整导致股价回踩 <strong>$100–$105 区间（股息率超 4.5%）</strong>则果断增配。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 税务与账户效率优化</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于其长期稳定的现金股息派发，建议优先置于免税账户或享受税收协定优惠的账户中，最大化 DRIP 长期复利效应。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-payxred-500/15 text-payxred-700 dark:text-payxred-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验派克西的业务整合与现金流回报：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 管理解决方案（Management Solutions）是否保持双位数高增速</span>\n <span class=\"text-[11px] font-mono text-payxred-600 dark:text-payxred-400 font-semibold shrink-0\">核心引擎增长锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 2026Q3 该板块大增 23% 至 $13.5 亿，需持续追踪 Paycor 整合后的销售协同与 ARPU 提升情况。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. PEO 业务工作现场雇员（WSE）留存率与增长势头</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">客户粘性晴雨表</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 PEO 收入增长 9% 达 $3.975 亿，需核查 WSE 留存率是否维持在历史最高位。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 营业利润率能否稳守 41%–43% 行业顶尖水平</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">费用控制与效率锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督整合 Paycor 带来的无形资产摊销及运营开支是否在预期控制范围内（Q3 营业利润率达 43.8%）。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 客户端资金托管利息（Interest on Client Funds）达成 $2.0B+ 目标</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">利息收益安全垫</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪 Q4 及后续宏观利率环境下，客户端资金池产生的利息收益是否达到 $2.0–$2.1 亿指引区间。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 美国中小企业宏观就业指数与新客户净增数量</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">宏观基本面领先指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 关注美国小企业雇主招聘意愿及 Paychex 整体 84 万家客户基础的净增变动。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444] focus:ring-payxred-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 自由现金流转化率及每季度股息派发与回购执行进度</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东现金回报放大器</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认每年超 15 亿美元的股东总回报（股息+回购）是否按计划稳健兑现。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>派克西 Paychex, Inc. (NASDAQ: PAYX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026 财年财报及 2026 年 11 月市场一致预期 (FY26)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于派克西公开财务报告（10-Q/10-K）、2026 财年业绩电话会议披露数据及全球人力资本管理（HCM）行业调研资料整理生成，旨在提供结构化的产业分析与红利成长资产估值框架。报告中涉及的盈利预测、Paycor 协同效益测算、三情景目标价及 DRIP 股息复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互脚本与 Chart.js -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-payxred-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-payxred-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-payxred-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-payxred-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentTaxRate = 0.10;\n\n function setTaxRate(rate) {\n currentTaxRate = rate;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnRate = parseFloat(btn.dataset.tax);\n if (Math.abs(btnRate - rate) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-payxred-500 text-white border border-payxred-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-payxred-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const drip = document.getElementById('drip-toggle').checked;\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initPrice = 115.68;\n const initDps = 4.76;\n const g = growthPct / 100;\n\n const initialShares = principal / initPrice;\n let shares = initialShares;\n let sharePrice = initPrice;\n let dps = initDps;\n let cashPool = 0;\n let cumulativeNetDiv = 0;\n\n for (let y = 1; y <= years; y++) {\n const grossDiv = shares * dps;\n const netDiv = grossDiv * (1 - currentTaxRate);\n cumulativeNetDiv += netDiv;\n\n const nextPrice = sharePrice * (1 + g);\n if (drip) {\n const avgReinvestPrice = (sharePrice + nextPrice) / 2;\n shares += netDiv / avgReinvestPrice;\n } else {\n cashPool += netDiv;\n }\n sharePrice = nextPrice;\n if (y < years) {\n dps = dps * (1 + g);\n }\n }\n\n const endForwardDps = initDps * Math.pow(1 + g, years);\n const endAnnualNetDiv = shares * endForwardDps * (1 - currentTaxRate);\n const finalPortfolioVal = (shares * sharePrice) + cashPool;\n const totalReturnPct = ((finalPortfolioVal - principal) / principal) * 100;\n const yieldOnCost = (endAnnualNetDiv / principal) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (${drip ? '含DRIP复利' : '现金分红留存'})`;\n document.getElementById('sim-annual-div').textContent = '$' + Math.round(endAnnualNetDiv).toLocaleString('en-US');\n document.getElementById('sim-monthly-div').textContent = `折合每月税后被动现金流 ~$${Math.round(endAnnualNetDiv / 12).toLocaleString('en-US')}`;\n document.getElementById('sim-yoc').textContent = yieldOnCost.toFixed(2) + '%';\n document.getElementById('sim-cum-div').textContent = '$' + Math.round(cumulativeNetDiv).toLocaleString('en-US');\n document.getElementById('sim-shares-end').textContent = `期末持仓股数：${shares.toFixed(1)} 股 (起始 ${initialShares.toFixed(1)} 股)`;\n }\n\n const KPI_STORAGE_KEY = 'payx_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const mixConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '管理解决方案营收 ($B)',\n data: [3.8, 4.1, 4.3, 4.5, 5.5],\n backgroundColor: '#EF4444',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: 'PEO 与保险解决方案营收 ($B)',\n data: [1.2, 1.3, 1.4, 1.5, 1.65],\n backgroundColor: '#F97316',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '总营收同比增速 (%)',\n data: [7.5, 6.2, 5.6, 12.0, 17.5],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 30,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => v + '%' }\n }\n }\n }\n };\n\n const metricsConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q3 总营收同比增速 (+20%)',\n 'Q3 管理解决方案增速 (+23%)',\n 'Q3 PEO 与保险增速 (+9%)',\n 'Q3 客户资金利息收入增速 (+33%)',\n '营业利润率 Operating Margin'\n ],\n datasets: [\n {\n label: '核心运营指标 (%)',\n data: [20.0, 23.0, 9.0, 33.0, 43.8],\n backgroundColor: ['#EF4444', '#F97316', '#3B82F6', '#10B981', '#8B5CF6'],\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `表现数值: +${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 60,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? mixConfig : metricsConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnMet = document.getElementById('btn-chart-met');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-payxred-600 dark:text-payxred-400 shadow-sm transition cursor-pointer';\n btnMet.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 净营收与管理解决方案分部演进';\n subEl.textContent = '得益于有机增长与 Paycor 并购赋能，管理解决方案营收实现跨越式增长';\n } else {\n btnMet.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-payxred-600 dark:text-payxred-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 各业务板块增速与核心运营指标拆解';\n subEl.textContent = 'Paycor 协同效应全面释放，管理解决方案飙升 23%，营业利润率坚挺在 43.8%';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '中小企业客户基础 (84万+)',\n 'CPA经纪人分销渠道壁垒',\n '税务合规与转换成本',\n '营业利润率与现金生成',\n '股息与股东现金回报'\n ],\n datasets: [\n {\n label: '派克西 (PAYX)',\n data: [9.6, 9.8, 9.7, 9.5, 9.8],\n borderColor: '#EF4444',\n backgroundColor: 'rgba(239, 68, 68, 0.24)',\n pointBackgroundColor: '#EF4444',\n borderWidth: 2.5\n },\n {\n label: 'ADP',\n data: [9.9, 9.2, 9.5, 9.0, 9.5],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: 'Paycom (PAYC)',\n data: [7.5, 7.0, 7.8, 7.2, 6.5],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '派克西 (PAYX · 中小企业HCM霸主)',\n 'ADP (全球HCM绝对龙头)',\n 'Paycom (PAYC · 纯云端SaaS)',\n 'Paylocity (PCTY · 现代科技HCM)'\n ],\n datasets: [\n {\n label: '营业利润率 Operating Margin (%)',\n data: [43.8, 25.0, 20.0, 18.0],\n backgroundColor: '#EF4444',\n borderRadius: 5,\n barThickness: 16\n },\n {\n label: '远期 P/E 估值倍数',\n data: [20.5, 26.0, 24.1, 21.4],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 16\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}${ctx.datasetIndex === 0 ? '%' : 'x'}`\n }\n }\n },\n scales: {\n x: {\n max: 55,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '总营业收入 Net Revenue ($B)',\n data: [4.24, 4.63, 5.02, 5.27, 5.57, 6.55],\n backgroundColor: 'rgba(239, 68, 68, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后稀释 EPS ($/股)',\n data: [3.42, 3.84, 4.31, 4.60, 4.85, 5.20],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '总营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 2,\n max: 6,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(2) },\n title: { display: true, text: '调整后 EPS ($/股)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
